, INFANT_RRN_FRONT = #{infantRrnFront}
, INFANT_RRN_BACK = #{infantRrnBack}
, MULTIPLE_BIRTH_YN = #{multipleBirthYn}
, PREMATURE_BABY_YN = #{prematureBabyYn}
, CONTRACT_START_DT = #{contractStartDt}
, CONTRACT_END_DT = #{contractEndDt}
, MATERNITY_LEAVE_PERIOD= #{maternityLeavePeriod}
, CURRENT_APPL_START_DT = #{currentApplStartDt}
, CURRENT_APPL_END_DT = #{currentApplEndDt}
, PAYMENT_ACCOUNT_NO = #{paymentAccountNo}
, BANK_NM = #{bankNm}
, ACCOUNT_HOLDER_NM = #{accountHolderNm}
, INCOME_YN = #{incomeYn}
, INCOME_TYPE = #{incomeType}
, INCOME_START_TIME = #{incomeStartTime}
, INCOME_END_TIME = #{incomeEndTime}
, WORK_HOURS = #{workHours}
